    let centred = tarvos_statistics_paired(x, y, "linear regression")?;
    let mx = x.iter().sum::<f64>() / x.len() as f64;
    let my = y.iter().sum::<f64>() / y.len() as f64;
    let sxx: f64 = x.iter().map(|v| (v - mx) * (v - mx)).sum();
