    fn emit_print_single(value: &Value, ctx: &EmitCtx) -> Result<(String, String)> {
        match value {
            // A name whose type changes is a tagged value. It has no inherent
            // `Display`, so it is rendered through the runtime helper, which is
            // also what makes a `Str` print without quotes and a list print
            // the way `print` shows one.
            Value::Name(name) if Self::is_dynamic(name) => {
                Ok(("{}".into(), format!("__tarvos_display(&{})", name)))
            }
            // Literal booleans: inline the Python-capitalised string directly
            Value::Bool(b) => {
                let lit = if *b { "True" } else { "False" };
                Ok(("{}".into(), format!("\"{}\"", lit)))
            }
            // Bool-typed expression (e.g., a comparison result): use an inline if
            Value::Binary { ty: Type::Bool, .. } => {
                let expr = Self::emit_value(value, ctx)?;
                Ok((
                    "{}".into(),
                    format!("if {} {{ \"True\" }} else {{ \"False\" }}", expr),
                ))
            }
            Value::Call {
                return_type: Type::Bool,
                ..
            } => {
                let expr = Self::emit_value(value, ctx)?;
                Ok((
                    "{}".into(),
                    format!("if {} {{ \"True\" }} else {{ \"False\" }}", expr),
                ))
            }
            // A float-typed expression has the same `4` vs `4.0` problem as a
            // float literal, so it is rendered through the display helper too.
            Value::Call {
                return_type: Type::Int | Type::String,
                ..
            }
            | Value::Binary {
                ty: Type::Int | Type::String,
                ..
            } => Ok(("{}".into(), Self::emit_value(value, ctx)?)),
            Value::Call {
                return_type: Type::Float,
                ..
            }
            | Value::Binary {
                ty: Type::Float, ..
            } => {
                let expr = Self::emit_value(value, ctx)?;
                Ok(("{}".into(), format!("(&({})).__tarvos_display()", expr)))
            }
            // Ints and strings have a Python-faithful `{}` rendering, but a
            // float does not: Rust prints an integral float as `4` while
            // Python prints `4.0`. The display helper formats with `{:?}`,
            // which keeps the fractional part Python's `str()` shows.
            Value::Int(_) | Value::Int128(_) | Value::String(_) => {
                Ok(("{}".into(), Self::emit_value(value, ctx)?))
            }
            Value::Float(_) => {
                let expr = Self::emit_value(value, ctx)?;
                Ok(("{}".into(), format!("(&({})).__tarvos_display()", expr)))
            }
            // An expression whose type is `Dynamic` is already a tagged value,
            // so it renders through the runtime helper. The typed display
            // trait has no impl for `__TarvosValue`, so calling it here would
            // emit code that does not compile.
            other if Self::value_is_dynamic(other) => {
                Ok(("{}".into(), Self::emit_value(other, ctx)?))
            }
            // For a Name that might be a bool we cannot know the runtime value
            // at codegen time without tracking types through every binding.
            other => {
                let expr = Self::emit_value(other, ctx)?;
                Ok(("{}".into(), format!("(&({})).__tarvos_display()", expr)))
            }
        }
    }

    /// Whether a value is statically a float, so a mixed numeric expression can
    /// promote the integer side to `f64`.
    fn value_is_float(value: &Value) -> bool {
        match value {
            Value::Float(_) => true,
            Value::Binary { ty, .. } => *ty == Type::Float,
            Value::Call { return_type, .. } => *return_type == Type::Float,
            Value::Unary { ty, .. } => *ty == Type::Float,
            _ => false,
        }
    }

    fn is_sequence_value(value: &Value) -> bool {
        match value {
            Value::String(_) | Value::List { .. } | Value::ListComp { .. } => true,
            Value::Call { return_type, .. } => {
                matches!(return_type, Type::Array(_) | Type::String)
            }
            Value::Slice { container_type, .. } => {
                matches!(container_type, Type::Array(_) | Type::String)
            }
            _ => false,
        }
    }

    /// Union of every display impl reachable from any statement in the module.
    fn collect_display_needs(module: &Module) -> DisplayNeeds {
        let names = Self::collect_name_types(module);
        let mut needs = DisplayNeeds::default();
        for stmt in &module.statements {
            Self::statement_require_display(stmt, &mut needs, &names);
        }
        needs
    }

    /// Best-effort `name -> type` map so a printed local resolves to one impl
    /// set instead of forcing the conservative fallback.
    fn collect_name_types(module: &Module) -> HashMap<String, Type> {
        let mut names: HashMap<String, Type> = HashMap::new();
        // Two passes: a `for` can read a name bound later in the module, so
        // collect the direct bindings first and resolve loop targets after.
        for stmt in &module.statements {
            match stmt {
                Stmt::Let { name, value, .. } | Stmt::Assign { name, value, .. } => {
                    if let Some(ty) = Self::infer_type(value) {
                        names.insert(name.clone(), ty);
                    }
                }
                Stmt::For { target, iter, .. } => {
                    if let Some(ty) = Self::iter_element_type(iter, &names) {
                        names.insert(target.clone(), ty);
                    }
                }
                _ => {}
            }
        }
        for stmt in &module.statements {
            if let Stmt::For { target, iter, .. } = stmt {
                if let Some(ty) = Self::iter_element_type(iter, &names) {
                    names.insert(target.clone(), ty);
                }
            }
        }
        names
    }

    fn iter_element_type(iter: &Value, names: &HashMap<String, Type>) -> Option<Type> {
        match iter {
            Value::List { element_type, .. } | Value::ListComp { element_type, .. } => {
                Some(element_type.clone())
            }
            // A list bound to a name resolves through the same map, otherwise
            // every `for` over a named list would fall back to all impls.
            Value::Name(name) => match names.get(name) {
                Some(Type::Array(inner)) => Some(*inner.clone()),
                _ => None,
            },
            _ => None,
        }
    }

    fn infer_type_ref(ty: &Type) -> Option<Type> {
        Some(ty.clone())
    }

    fn infer_type(value: &Value) -> Option<Type> {
        Some(match value {
            Value::Int(_) | Value::Int128(_) => Type::Int,
            Value::Float(_) => Type::Float,
            Value::Bool(_) => Type::Bool,
            Value::String(_) => Type::String,
            Value::List { element_type, .. } | Value::ListComp { element_type, .. } => {
                Type::Array(Box::new(element_type.clone()))
            }
            Value::Tuple { element_types, .. } => Type::Tuple(element_types.clone()),
            Value::Dict {
                key_type,
                value_type,
                ..
            } => Type::Dict {
                key: Box::new(key_type.clone()),
                value: Box::new(value_type.clone()),
            },
            Value::Binary { ty, .. } | Value::Unary { ty, .. } => ty.clone(),
            Value::Index { element_type, .. } => element_type.clone(),
            // `range()` becomes a Rust `Range` and is handled by the caller.
            _ => return None,
        })
    }

    fn statement_require_display(
        stmt: &Stmt,
        needs: &mut DisplayNeeds,
        names: &HashMap<String, Type>,
    ) {
        match stmt {
            Stmt::Print(values) => {
                for value in values {
                    Self::require_display(value, needs, names);
                }
            }
            Stmt::If { body, orelse, .. } => {
                for stmt in body {
                    Self::statement_require_display(stmt, needs, names);
                }
                for stmt in orelse {
                    Self::statement_require_display(stmt, needs, names);
                }
            }
            Stmt::While { body, .. } => {
                for stmt in body {
                    Self::statement_require_display(stmt, needs, names);
                }
            }
            Stmt::For { body, .. } => {
                for stmt in body {
                    Self::statement_require_display(stmt, needs, names);
                }
            }
            Stmt::Function { body, .. } => {
                for stmt in body {
                    Self::statement_require_display(stmt, needs, names);
                }
            }
            Stmt::Try {
                body,
                handlers,
                orelse,
                finalbody,
            } => {
                for stmt in body {
                    Self::statement_require_display(stmt, needs, names);
                }
                for handler in handlers {
                    for stmt in &handler.body {
                        Self::statement_require_display(stmt, needs, names);
                    }
                }
                for stmt in orelse {
                    Self::statement_require_display(stmt, needs, names);
                }
                for stmt in finalbody {
                    Self::statement_require_display(stmt, needs, names);
                }
            }
            Stmt::With { body, .. } => {
                for stmt in body {
                    Self::statement_require_display(stmt, needs, names);
                }
            }
            // A binding is only stringified when it is an f-string; any other
            // assignment is emitted as the value itself.
            Stmt::Let { value, .. } | Stmt::Assign { value, .. } => {
                Self::require_if_formatted(value, needs, names)
            }
            Stmt::Expr(value) => Self::require_if_formatted(value, needs, names),
            // `raise` renders its argument into the exception message.
            Stmt::Raise(Some(value)) => Self::require_display(value, needs, names),
            Stmt::FieldAssign { .. }
            | Stmt::IndexAssign { .. }
            | Stmt::Destructure { .. }
            | Stmt::ListAppend { .. }
            | Stmt::Return(Some(_)) => {}
            Stmt::StructDef { .. }
            | Stmt::Break
            | Stmt::Continue
            | Stmt::Raise(None)
            | Stmt::Return(None) => {}
        }
    }

    /// An f-string is the only non-`print` construct that stringifies a value.
    fn require_if_formatted(
        value: &Value,
        needs: &mut DisplayNeeds,
        names: &HashMap<String, Type>,
    ) {
        if Self::contains_format(value) {
            Self::require_display(value, needs, names);
        }
    }

    fn contains_format(value: &Value) -> bool {
        match value {
            Value::FormatString { .. } => true,
            Value::Binary { left, right, .. } => {
                Self::contains_format(left) || Self::contains_format(right)
            }
            Value::Unary { operand, .. } => Self::contains_format(operand),
            _ => false,
        }
    }

    /// Record which display/repr impls a single value can reach.
    ///
    /// An unresolvable value falls back to every impl. That keeps this pass
    /// strictly narrowing: it can only remove code that was already emitted,
    /// never drop an impl the generated program still needs.
    fn require_display(value: &Value, needs: &mut DisplayNeeds, names: &HashMap<String, Type>) {
        match value {
            // Scalars with a Python-faithful `{}` rendering never call the helper.
            Value::Int(_) | Value::Int128(_) | Value::String(_) | Value::Bool(_) => {}
            Value::Float(_) => {
                // Rust's `{}` prints an integral float as `4`; Python's `str(4.0)`
                // is `4.0`, so this genuinely needs the `{:?}` helper.
                needs.display_f64 = true;
                needs.repr_f64 = true;
            }
            Value::List {
                elements,
                element_type,
            } => {
                needs.display_collection = true;
                needs.repr_collection = true;
                Self::require_type_repr(element_type, needs);
                for element in elements {
                    Self::require_display(element, needs, names);
                }
            }
            Value::ListComp { element_type, .. } => {
                needs.display_collection = true;
                needs.repr_collection = true;
                Self::require_type_repr(element_type, needs);
            }
            Value::Tuple {
                element_types,
                elements,
            } => {
                needs.display_collection = true;
                needs.repr_collection = true;
                for ty in element_types {
                    Self::require_type_repr(ty, needs);
                }
                for element in elements {
                    Self::require_display(element, needs, names);
                }
            }
            Value::Dict {
                key_type,
                value_type,
                ..
            } => {
                needs.display_collection = true;
                needs.repr_collection = true;
                Self::require_type_repr(key_type, needs);
                Self::require_type_repr(value_type, needs);
            }
            Value::Call {
                function,
                return_type,
                args,
            } => {
                // `range()` is lowered to a Rust `Range`, so it needs the range
                // impls even though its Python type is Int.
                if function == "range" {
                    needs.display_range = true;
                    needs.repr_range = true;
                } else {
                    Self::require_type_display(return_type, needs);
                }
                // Arguments are passed to the callee, not rendered by the call
                // site, so `len(xs)` must not pull in the list display impls.
                // `str`/`repr` are the builtins that genuinely stringify.
                if function == "str" || function == "repr" {
                    for arg in args {
                        Self::require_display(arg, needs, names);
                    }
                }
            }
            Value::Binary {
                left, right, ty, ..
            } => {
                Self::require_type_display(ty, needs);
                Self::require_display(left, needs, names);
                Self::require_display(right, needs, names);
            }
            Value::Unary { operand, ty, .. } => {
                Self::require_type_display(ty, needs);
                Self::require_display(operand, needs, names);
            }
            Value::Index {
                element_type,
                container,
                index,
                ..
            } => {
                Self::require_type_display(element_type, needs);
                Self::require_display(container, needs, names);
                Self::require_display(index, needs, names);
            }
            Value::FormatString { parts } => {
                for part in parts {
                    if let FormatPart::Value { value, .. } = part {
                        Self::require_display(value, needs, names);
                    }
                }
            }
            Value::Name(name) => match names.get(name).and_then(Self::infer_type_ref) {
                Some(ty) => Self::require_type_display(&ty, needs),
                // The type is only known to the semantic layer, so emitting
                // everything is the only safe answer.
                None => needs.require_all(),
            },
            // A field or slice type is not resolvable here, so fall back to
            // every impl rather than risk dropping one the program needs.
            Value::Field { .. } | Value::Slice { .. } => needs.require_all(),
        }
    }

    /// Impls needed for a value of known type reaching `__tarvos_display`.
    fn require_type_display(ty: &Type, needs: &mut DisplayNeeds) {
        match ty {
            Type::Int => needs.display_i64 = true,
            Type::Float => {
                needs.display_f64 = true;
                needs.repr_f64 = true;
            }
            Type::Bool => {
                needs.display_bool = true;
                needs.repr_bool = true;
            }
            Type::String => {
                needs.display_string = true;
                needs.repr_string = true;
            }
            // The `Vec`/`HashMap` impls are generic over their element type and
            // the bound is checked at instantiation, so a `Vec<i64>` display
            // also needs `Repr for i64`. Recursing here is what keeps the
            // emitted set compilable.
            Type::Array(inner) => {
                needs.display_collection = true;
                needs.repr_collection = true;
                Self::require_type_repr(inner, needs);
            }
            Type::Tuple(elements) => {
                needs.display_collection = true;
                needs.repr_collection = true;
                for ty in elements {
                    Self::require_type_repr(ty, needs);
                }
            }
            Type::Dict { key, value } => {
                needs.display_collection = true;
                needs.repr_collection = true;
                Self::require_type_repr(key, needs);
                Self::require_type_repr(value, needs);
            }
            _ => needs.require_all(),
        }
    }

    /// A generic `Vec`/`HashMap` impl is only usable if its element type also
    /// has a `Repr` impl, because the bound is checked at instantiation.
    fn require_type_repr(ty: &Type, needs: &mut DisplayNeeds) {
        match ty {
            Type::Int => needs.repr_i64 = true,
            Type::Float => needs.repr_f64 = true,
            Type::Bool => needs.repr_bool = true,
            Type::String => needs.repr_string = true,
            Type::Array(inner) => {
                needs.repr_collection = true;
                Self::require_type_repr(inner, needs);
            }
            Type::Tuple(elements) => {
                needs.repr_collection = true;
                for ty in elements {
                    Self::require_type_repr(ty, needs);
                }
            }
            Type::Dict { key, value } => {
                needs.repr_collection = true;
                Self::require_type_repr(key, needs);
                Self::require_type_repr(value, needs);
            }
            _ => needs.require_all(),
        }
    }

    /// Route an operation that can fail to the innermost `try`, when there is one.
    ///
    /// Python raises instead of trapping: `1 / 0` is an exception, not a trap and
    /// not a sentinel value. The previous lowering called `.expect(...)` or
    /// `panic!`, which aborted the native process, so an enclosing
    /// `except ZeroDivisionError` never ran and the program died instead of
    /// recovering. With a `try` in scope the failure travels as a `Result` and
    /// jumps to the handler, matching the way a call to a fallible function
    /// already propagates.
    ///
    /// Without a `try` there is nothing to catch, so the expression stays a
    /// panic: that is the honest rendering of an uncaught exception and keeps the
    /// no-handler path from growing a `Result` it would immediately discard.
    fn raise_aware(ctx: &EmitCtx, checked: &str, panicking: &str) -> String {
        match ctx.try_stack.last().cloned() {
            Some((label, error_var)) => format!(
                "match {checked} {{ Ok(__tarvos_v) => __tarvos_v, Err(__tarvos_e) => {{ {error_var} = Some(__tarvos_e); break '{label}; }} }}"
            ),
            None => panicking.to_string(),
        }
    }

    fn emit_value(value: &Value, ctx: &EmitCtx) -> Result<String> {
        Ok(match value {
            Value::Int(v) => format!("{}_i64", v),
            Value::Int128(v) => format!("{}_u128", v),
            Value::Float(v) => {
                // Ensure floats always have a decimal point for Rust literal validity
                if v.fract() == 0.0 {
                    format!("{}.0_f64", v)
                } else {
                    format!("{}_f64", v)
                }
            }
            // Strings are stored as Rust `String` (heap), not `&str`
            Value::String(v) => format!("{:?}.to_string()", v),
            Value::Bool(v) => v.to_string(),
            Value::Name(name) if name == "__name__" => "\"__main__\".to_string()".to_string(),
            Value::Name(name) => name.clone(),
            Value::Field { object, field, .. } => {
                let object = Self::emit_value(object, ctx)?;
                let object = if object == "self" {
                    "self_obj".to_string()
                } else {
                    object
                };
                format!("{}.{}", object, field)
            }
            Value::Unary { op, operand, .. } => {
                let operand = Self::emit_value(operand, ctx)?;
                match op {
                    tarvos_ir::UnaryOp::Neg => format!("-({})", operand),
                    tarvos_ir::UnaryOp::Not => format!("!({})", operand),
                    tarvos_ir::UnaryOp::Invert => format!("!({})", operand),
                }
            }
            Value::Binary {
                left,
                op,
                right,
                ty,
            } => {
                // An operation on a tagged value goes through the runtime
                // dispatcher, which is what makes `x + 1` work when `x` holds a
                // string as well as when it holds an int. The result is a
                // tagged value again, so a later operation on it still works.
                if Self::is_dynamic_operand(left) || Self::is_dynamic_operand(right) {
                    // Equality is checked before the arithmetic table, because
                    // `dynamic_binop` has no entry for it: comparing two tagged
                    // values is Python's value equality, not a numeric op.
                    if matches!(op, BinaryOp::Eq | BinaryOp::NotEq) {
                        let left_str = Self::box_dynamic(left)?;
                        let right_str = Self::box_dynamic(right)?;
                        return Ok(format!("__tarvos_eq(&{}, &{})", left_str, right_str));
                    }
                    if let Some(runtime_op) = Self::dynamic_binop(op) {
                        let left_str = Self::box_dynamic(left)?;
                        let right_str = Self::box_dynamic(right)?;
                        return Ok(format!(
                            "__tarvos_binop(&{}, &{}, tarvos_binop::Op::{})",
                            left_str,
                            right_str,
                            RustCodegen::right_op_name(runtime_op)
                        ));
                    }
                }
                let left_str = Self::emit_value(left, ctx)?;
                let right_str = Self::emit_value(right, ctx)?;
                if *op == BinaryOp::Pow {
                    return Ok(match ty {
                        Type::Int => format!(
                            "if {} < 0 {{ panic!(\"negative integer exponent is unsupported\") }} else {{ {}.checked_pow({} as u32).expect(\"integer power overflow\") }}",
                            right_str, left_str, right_str
                        ),
                        Type::Float => format!("({} as f64).powf({} as f64)", left_str, right_str),
                        _ => return Err(anyhow::anyhow!("power requires numeric operands")),
                    });
                }
                if *op == BinaryOp::Mul && matches!(ty, Type::Array(_) | Type::String) {
                    let (sequence, count) = if Self::is_sequence_value(left) {
                        (left_str, right_str)
                    } else {
                        (right_str, left_str)
                    };
                    return Ok(format!("({}).repeat(({} as usize))", sequence, count));
                }
                if *op == BinaryOp::Div && *ty == Type::Int {
                    return Ok(Self::raise_aware(
                        ctx,
                        &format!("__tarvos_div_i64({}, {})", left_str, right_str),
                        &format!(
                            "{}.checked_div({}).expect(\"ZeroDivisionError\")",
                            left_str, right_str
                        ),
                    ));
                }
                if *op == BinaryOp::Div
                    && *ty == Type::Float
                    && matches!(left.as_ref(), Value::Int(_))
                    && matches!(right.as_ref(), Value::Int(_))
                {
                    return Ok(Self::raise_aware(
                        ctx,
                        &format!("__tarvos_div_f64({} as f64, {} as f64)", left_str, right_str),
                        &format!(
                            "if {} == 0_i64 {{ panic!(\"ZeroDivisionError\") }} else {{ ({} as f64) / ({} as f64) }}",
                            right_str, left_str, right_str
                        ),
                    ));
                }
                // Float `/` where the operands are not both literals. Without this
                // the generic operator table emits a bare `a / b`, and a zero
                // divisor silently produces an infinity instead of raising, so an
                // `except ZeroDivisionError` never runs.
                if *op == BinaryOp::Div && *ty == Type::Float {
                    // Python's `/` is true division, so integer operands are
                    // promoted. The cast is applied unconditionally because an
                    // `as f64` on a value that is already `f64` is a no-op, and
                    // without it an `i64` operand is passed where `f64` is
                    // expected.
                    return Ok(Self::raise_aware(
                        ctx,
                        &format!(
                            "__tarvos_div_f64({} as f64, {} as f64)",
                            left_str, right_str
                        ),
                        &format!(
                            "{{ if {} == 0.0_f64 {{ panic!(\"ZeroDivisionError: float division\") }} else {{ ({} as f64) / ({} as f64) }} }}",
                            right_str, left_str, right_str
                        ),
                    ));
                }
                if *op == BinaryOp::FloorDiv && *ty == Type::Int {
                    // Python `//` floors toward negative infinity; Rust `/` truncates.
                    // Python `//` floors toward negative infinity; Rust `/` truncates.
                    return Ok(Self::raise_aware(
                        ctx,
                        &format!(
                            "__tarvos_floor_div_i64({}, {})",
                            left_str, right_str
                        ),
                        &format!(
                            "{{ let __tarvos_dividend = {left_str}; let __tarvos_divisor = {right_str}; if __tarvos_divisor == 0_i64 {{ panic!(\"ZeroDivisionError: integer division or modulo by zero\") }} let __tarvos_quotient = __tarvos_dividend.checked_div(__tarvos_divisor).expect(\"integer division overflow\"); let __tarvos_remainder = __tarvos_dividend.checked_rem(__tarvos_divisor).expect(\"integer division overflow\"); if __tarvos_remainder != 0_i64 && ((__tarvos_remainder < 0_i64) != (__tarvos_divisor < 0_i64)) {{ __tarvos_quotient - 1_i64 }} else {{ __tarvos_quotient }} }}"
                        ),
                    ));
                }
                if *op == BinaryOp::FloorDiv && *ty == Type::Float {
                    let left_str = if matches!(left.as_ref(), Value::Int(_)) {
                        format!("({} as f64)", left_str)
                    } else {
                        left_str
                    };
                    let right_str = if matches!(right.as_ref(), Value::Int(_)) {
                        format!("({} as f64)", right_str)
                    } else {
                        right_str
                    };
                    return Ok(Self::raise_aware(
                        ctx,
                        &format!(
                            "__tarvos_floor_div_f64({}, {})",
                            left_str, right_str
                        ),
                        // Without the guard this is `(a / b).floor()`, which
                        // yields an infinity for a zero divisor. CPython raises,
                        // so the no-handler path keeps an explicit failure.
                        &format!("{{ if {} == 0.0_f64 {{ panic!(\"ZeroDivisionError: float floor division\") }} else {{ ({} / {}).floor() }} }}", right_str, left_str, right_str),
                    ));
                }
                if *op == BinaryOp::LShift || *op == BinaryOp::RShift {
                    // Python shifts by a negative count raise ValueError. Counts larger
                    // than the native i64 width saturate: `>>` yields 0 or -1 (the sign
                    // extension), while `<<` can no longer be represented and panics.
                    let fallback = if *op == BinaryOp::LShift {
                        "unwrap_or_else(|| if __tarvos_shift_value == 0_i64 { 0_i64 } else { panic!(\"integer shift overflow: left shift exceeds the native i64 range\") })"
                    } else {
                        "unwrap_or_else(|| if __tarvos_shift_value < 0_i64 { -1_i64 } else { 0_i64 })"
                    };
                    let checked = if *op == BinaryOp::LShift {
                        "checked_shl"
                    } else {
                        "checked_shr"
                    };
                    return Ok(format!(
                        "{{ let __tarvos_shift_amount = {right_str}; if __tarvos_shift_amount < 0_i64 {{ panic!(\"ValueError: negative shift count\") }} let __tarvos_shift_value = {left_str}; __tarvos_shift_value.{checked}(__tarvos_shift_amount as u32).{fallback} }}"
                    ));
                }
                let op_str = op.symbol();
                // Python compares numbers across int and float (`1 == 1.0` is
                // True), so a mixed comparison has to promote the integer side.
                // Emitting `1_i64 == 1.0_f64` is not even valid Rust.
                if matches!(
                    op,
                    BinaryOp::Eq
                        | BinaryOp::NotEq
                        | BinaryOp::Lt
                        | BinaryOp::LtEq
                        | BinaryOp::Gt
                        | BinaryOp::GtEq
                ) {
                    let left_is_float = Self::value_is_float(left);
                    let right_is_float = Self::value_is_float(right);
                    if left_is_float != right_is_float {
                        let (left_str, right_str) = if left_is_float {
                            (left_str, format!("({right_str} as f64)"))
                        } else {
                            (format!("({left_str} as f64)"), right_str)
                        };
                        return Ok(format!("({left_str}) {op_str} ({right_str})"));
                    }
                }

                if *ty == Type::String && *op == BinaryOp::Add {
                    format!("format!(\"{{}}{{}}\", {}, {})", left_str, right_str)
                } else if *ty == Type::Float {
                    // Promote every operand that is not already a float. The
                    // previous check only cast integer *literals*, so an
                    // expression like `total / count` (two call results) kept
                    // integer types and the division stayed integral, which is
                    // both a type error against a float return and wrong for
                    // Python's true division.
                    let left_str = if Self::value_is_float(left) {
                        left_str
                    } else {
                        format!("({} as f64)", left_str)
                    };
                    let right_str = if Self::value_is_float(right) {
                        right_str
                    } else {
                        format!("({} as f64)", right_str)
                    };
                    format!("({} {} {})", left_str, op_str, right_str)
                } else {
                    format!("({} {} {})", left_str, op_str, right_str)
                }
            }
            Value::Call {
                function,
                args,
                return_type,
            } => {
                // A user function takes its parameters by value, so passing an
                // owned binding (a Vec or String) would move it and make a later
                // use of the same variable a compile error. Clone those
                // arguments.
                //
                // This is restricted to user functions on purpose. The runtime
                // helpers take `&mut` receivers and mutate in place, so cloning
                // their receiver would silently discard the mutation and leave
                // the original list unchanged.
                let owned = if Self::is_user_function(function) {
                    Self::owned_bindings(args)
                } else {
                    vec![false; args.len()]
                };
                let args_rendered = args
                    .iter()
                    .zip(owned)
                    .map(|(arg, needs_clone)| {
                        let rendered = Self::emit_value(arg, ctx)?;
                        Ok(if needs_clone {
                            format!("{rendered}.clone()")
                        } else {
                            rendered
                        })
                    })
                    .collect::<Result<Vec<_>>>()?;
                let args_str = args_rendered.join(", ");

                // A function that can raise returns a `Result`. Inside a `try` the
                // error is handed to that try; with no handler the call terminates,
                // which is what an uncaught exception does in Python.
                if ctx.fallible.contains(function) {
                    let call = format!("{function}({args_str})");
                    return Ok(match ctx.try_stack.last().cloned() {
                        Some((label, error_var)) => format!(
                            "match {call} {{ Ok(__tarvos_v) => __tarvos_v, Err(__tarvos_e) => {{ {error_var} = Some(__tarvos_e); break '{label}; }} }}"
                        ),
                        None => format!(
                            "{call}.unwrap_or_else(|__tarvos_e| __tarvos_uncaught(&__tarvos_e))"
                        ),
                    });
                }

                match function.as_str() {
                    name if name.starts_with("__tarvos_ctor_") => {
                        format!("{}({})", name, args_str)
                    }
                    // `json.dumps(x)` on a value computed at run time.
                    "tarvos_json_dumps_runtime" => {
                        format!("(&({})).__tarvos_json()", args_str)
                    }
                    // A statistics function reads its sequences; the call must
                    // borrow rather than move, or the program would consume the
                    // caller's list on the first call. It also reports errors
                    // through a `Result`, so the call site unwraps it the same way a
                    // fallible function call does.
                    name if name.starts_with("tarvos_statistics_") => {
                        // CPython's trailing arguments are optional and the native
                        // functions take them positionally, so the defaults are
                        // injected here. Only the *sequence* arguments are borrowed;
                        // a scalar argument such as `interval` must not be.
                        //
                        // Arity is checked rather than padded blindly, because a short
                        // call that reached Rust unchecked would surface as an opaque
                        // arity error instead of a Tarvos diagnostic.
                        let (leading_sequences, defaults): (usize, &[&str]) = match name {
                            "tarvos_statistics_median_grouped" => (1, &["1.0_f64"]),
                            "tarvos_statistics_quantiles" => (1, &[]),
                            "tarvos_statistics_covariance"
                            | "tarvos_statistics_correlation"
                            | "tarvos_statistics_linear_regression" => (2, &[]),
                            _ => (1, &[]),
                        };
                        let maximum = leading_sequences + defaults.len();
                        if args_rendered.len() < leading_sequences
                            || args_rendered.len() > maximum
                        {
                            return Err(anyhow::anyhow!(
                                "{name}() takes {leading_sequences}..={maximum} argument(s); \
                                 keyword arguments are not lowered by the native backend yet"
                            ));
                        }
                        let mut rendered: Vec<String> = args_rendered
                            .iter()
                            .enumerate()
                            .map(|(position, a)| {
                                if position < leading_sequences {
                                    format!("&{a}")
                                } else {
                                    a.clone()
                                }
                            })
                            .collect();
                        for (position, default) in defaults.iter().enumerate() {
                            if rendered.len() <= leading_sequences + position {
                                rendered.push((*default).to_string());
                            }
                        }
                        let call = format!("{name}({})", rendered.join(", "));
                        match ctx.try_stack.last().cloned() {
                            Some((label, error_var)) => format!(
                                "match {call} {{ Ok(__tarvos_v) => __tarvos_v, Err(__tarvos_e) => {{ {error_var} = Some(__tarvos_e); break '{label}; }} }}"
                            ),
                            None => format!(
                                "{call}.unwrap_or_else(|__tarvos_e| __tarvos_uncaught(&__tarvos_e))"
                            ),
                        }
                    }
                    name if name.starts_with("__tarvos_mut_call_") => {
                        let function = name.trim_start_matches("__tarvos_mut_call_");
                        let Some((receiver, rest)) = args_rendered.split_first() else {
                            return Err(anyhow::anyhow!("method call missing receiver"));
                        };
                        let mut call_args = vec![format!("&mut {}", receiver)];
                        call_args.extend(rest.iter().cloned());
                        format!("{}({})", function, call_args.join(", "))
                    }
                    // print() used as an expression: use Python display semantics
                    "print" => format!("println!(\"{{}}\", {})", args_str),
                    "range" => match args_rendered.as_slice() {
                        [stop] => format!("(0..{stop})"),
                        [start, stop] => format!("({start}..{stop})"),
                        [start, stop, step] => Self::emit_range_step(
                            start,
                            stop,
                            step,
                            // `args` and `args_rendered` are parallel, so the same
                            // index selects the step's static value.
                            args.get(2),
                        ),
                        _ => return Err(anyhow::anyhow!("range() requires 1 to 3 arguments")),
                    },
                    "len" => format!("({}.len() as i64)", args_str),
                    // `str(x)` must reproduce Python's `str`. Rust's `{}` prints
                    // `true` for a bool and `4` for an integral float, where
                    // Python prints `True` and `4.0`.
                    "str" => Self::emit_str_conversion(&args[0], &args_rendered[0]),
                    "int" => Self::emit_int_conversion(&args[0], &args_rendered[0]),
                    "float" => Self::emit_float_conversion(&args[0], &args_rendered[0]),
                    "bool" => Self::emit_truthiness(&args[0], &args_rendered[0]),
                    "tarvos_perf_counter" => {
                        "std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).expect(\"system clock\").as_secs_f64()".to_string()
                    }
                    "tarvos_time" => {
                        "std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).expect(\"system clock\").as_secs_f64()".to_string()
                    }
                    "tarvos_sleep" => match args_rendered.as_slice() {
                        [seconds] => format!(
                            "std::thread::sleep(std::time::Duration::from_secs_f64({} as f64))",
                            seconds
                        ),
                        _ => return Err(anyhow::anyhow!("time.sleep() requires 1 argument")),
                    },
                    // `str` builtins: the receiver arrives first, so a borrow keeps
                    // the call from moving out of the binding it came from.
                    name if name.starts_with("tarvos_str_") => {
                        Self::emit_str_builtin(name, &args_rendered)?
                    }
                    name if name.starts_with("tarvos_list_") => {
                        Self::emit_list_builtin(name, &args_rendered)?
                    }
                    "tarvos_os_getcwd" => {
                        if !args_rendered.is_empty() {
                            return Err(anyhow::anyhow!("os.getcwd() takes no arguments"));
                        }
                        "std::env::current_dir().expect(\"os.getcwd() failed\").to_string_lossy().into_owned()"
                            .to_string()
                    }
                    "tarvos_os_listdir" => match args_rendered.as_slice() {
                        [] => "std::fs::read_dir(\".\").expect(\"os.listdir() failed\").filter_map(|entry| entry.ok()).filter_map(|entry| entry.file_name().into_string().ok()).collect::<Vec<String>>()".to_string(),
                        [path] => format!(
                            "std::fs::read_dir({}).expect(\"os.listdir() failed\").filter_map(|entry| entry.ok()).filter_map(|entry| entry.file_name().into_string().ok()).collect::<Vec<String>>()",
                            path
                        ),
                        _ => return Err(anyhow::anyhow!("os.listdir() takes at most 1 argument")),
                    },
                    "tarvos_os_mkdir" => match args_rendered.as_slice() {
                        [path] => format!(
                            "std::fs::create_dir({}).expect(\"os.mkdir() failed\")",
                            path
                        ),
                        _ => return Err(anyhow::anyhow!("os.mkdir() requires 1 argument")),
                    },
                    "tarvos_os_makedirs" => match args_rendered.as_slice() {
                        [path] => format!(
                            "std::fs::create_dir_all({}).expect(\"os.makedirs() failed\")",
                            path
                        ),
                        [path, exist_ok] => format!(
                            "if {} {{ std::fs::create_dir_all({}).expect(\"os.makedirs() failed\") }} else {{ std::fs::create_dir({}).expect(\"os.makedirs() failed\") }}",
                            exist_ok, path, path
                        ),
                        _ => return Err(anyhow::anyhow!("os.makedirs() requires 1 or 2 arguments")),
                    },
                    "tarvos_os_chdir" => match args_rendered.as_slice() {
                        [path] => format!(
                            "std::env::set_current_dir({}).expect(\"os.chdir() failed\")",
                            path
                        ),
                        _ => return Err(anyhow::anyhow!("os.chdir() requires 1 argument")),
                    },
                    "tarvos_math_sqrt"
                    | "tarvos_math_sin"
                    | "tarvos_math_cos"
                    | "tarvos_math_tan"
                    | "tarvos_math_asin"
                    | "tarvos_math_acos"
                    | "tarvos_math_atan"
                    | "tarvos_math_exp"
                    | "tarvos_math_log"
                    | "tarvos_math_log10"
                    | "tarvos_math_fabs"
                    | "tarvos_math_isfinite"
                    | "tarvos_math_isnan"
                    | "tarvos_math_isinf" => {
                        let [value] = args_rendered.as_slice() else {
                            return Err(anyhow::anyhow!(
                                "{}() requires 1 argument",
                                function
                            ));
                        };
                        let method = match function.as_str() {
                            "tarvos_math_sqrt" => "sqrt",
                            "tarvos_math_sin" => "sin",
                            "tarvos_math_cos" => "cos",
                            "tarvos_math_tan" => "tan",
                            "tarvos_math_asin" => "asin",
                            "tarvos_math_acos" => "acos",
                            "tarvos_math_atan" => "atan",
                            "tarvos_math_exp" => "exp",
                            "tarvos_math_log" => "ln",
                            "tarvos_math_log10" => "log10",
                            "tarvos_math_fabs" => "abs",
                            "tarvos_math_isfinite" => "is_finite",
                            "tarvos_math_isnan" => "is_nan",
                            "tarvos_math_isinf" => "is_infinite",
                            _ => unreachable!(),
                        };
                        format!("({} as f64).{}()", value, method)
                    }
                    "tarvos_math_floor" | "tarvos_math_ceil" => {
                        let [value] = args_rendered.as_slice() else {
                            return Err(anyhow::anyhow!(
                                "{}() requires 1 argument",
                                function
                            ));
                        };
                        let method = if function == "tarvos_math_floor" {
                            "floor"
                        } else {
                            "ceil"
                        };
                        format!("({} as f64).{}() as i64", value, method)
                    }
                    "tarvos_math_pow" => match args_rendered.as_slice() {
                        [base, exponent] => {
                            format!("({} as f64).powf({} as f64)", base, exponent)
                        }
                        _ => return Err(anyhow::anyhow!("math.pow() requires 2 arguments")),
                    },
                    "tarvos_math_hypot" => match args_rendered.as_slice() {
                        [left, right] => {
                            format!("({} as f64).hypot({} as f64)", left, right)
                        }
                        _ => return Err(anyhow::anyhow!("math.hypot() requires 2 arguments")),
                    },
                    "tarvos_math_atan2" => match args_rendered.as_slice() {
                        [left, right] => {
                            format!("({} as f64).atan2({} as f64)", left, right)
                        }
                        _ => return Err(anyhow::anyhow!("math.atan2() requires 2 arguments")),
                    },
                    "tarvos_os_path_join" => {
                        if args_rendered.len() < 2 {
                            return Err(anyhow::anyhow!(
                                "os.path.join() requires at least 2 arguments"
                            ));
                        }
                        let mut expression =
                            format!("std::path::PathBuf::from({})", args_rendered[0]);
                        for argument in &args_rendered[1..] {
                            expression = format!("{}.join({})", expression, argument);
                        }
                        format!("{}.to_string_lossy().into_owned()", expression)
                    }
                    "tarvos_os_path_basename"
                    | "tarvos_os_path_dirname"
                    | "tarvos_os_path_exists"
                    | "tarvos_os_path_isfile"
                    | "tarvos_os_path_isdir" => {
                        let [path] = args_rendered.as_slice() else {
                            return Err(anyhow::anyhow!(
                                "{}() requires 1 argument",
                                function
                            ));
                        };
                        match function.as_str() {
                            "tarvos_os_path_basename" => format!(
                                "std::path::Path::new(&{}).file_name().map(|v| v.to_string_lossy().into_owned()).unwrap_or_default()",
                                path
                            ),
                            "tarvos_os_path_dirname" => format!(
                                "std::path::Path::new(&{}).parent().map(|v| v.to_string_lossy().into_owned()).unwrap_or_default()",
                                path
                            ),
                            "tarvos_os_path_exists" => {
                                format!("std::path::Path::new(&{}).exists()", path)
                            }
                            "tarvos_os_path_isfile" => {
                                format!("std::path::Path::new(&{}).is_file()", path)
                            }
                            "tarvos_os_path_isdir" => {
                                format!("std::path::Path::new(&{}).is_dir()", path)
                            }
                            _ => unreachable!(),
                        }
                    }
                    "abs" => format!("({}).abs()", args_str),
                    "min" => match args_rendered.as_slice() {
                        [a, b] => format!("({}).min({})", a, b),
                        _ => format!("std::cmp::min({})", args_str),
                    },
                    "max" => match args_rendered.as_slice() {
                        [a, b] => format!("({}).max({})", a, b),
                        _ => format!("std::cmp::max({})", args_str),
                    },
                    "sum" => format!("{}.iter().sum::<i64>()", args_str),
                    name
                        if name.starts_with("__tarvos_list_from_")
                            | name.starts_with("__tarvos_sorted_from_") =>
                    {
                        Self::emit_list_or_sorted_call(name, args, &args_rendered, return_type)?
                    },
                    "__ternary" => match args_rendered.as_slice() {
                        [test, body, orelse] => format!("(if {} {{ {} }} else {{ {} }})", test, body, orelse),
                        _ => return Err(anyhow::anyhow!("__ternary requires 3 arguments")),
                    },
                    _ => {
                        let function = if function == "main" {
                            "__tarvos_main"
                        } else {
                            function.as_str()
                        };
                        format!("{}({})", function, args_str)
                    }
                }
            }
            Value::List {
                elements,
                element_type,
            } => {
                if elements.is_empty() && *element_type == Type::Unknown {
                    // `list()` with no evidence keeps `Unknown` so validation can
                    // still reject it as dynamic; emission annotates the vec so
                    // the display helper resolves without guessing the element.
                    return Ok("Vec::<i64>::new()".to_string());
                }
                let elements_str = elements
                    .iter()
                    .map(|v| Self::emit_value(v, ctx))
                    .collect::<Result<Vec<_>>>()?
                    .join(", ");
                format!("vec![{}]", elements_str)
            }
            Value::ListComp {
                target,
                iter,
                element,
                condition,
                ..
            } => {
                let iter_str = Self::emit_value(iter, ctx)?;
                let element_str = Self::emit_value(element, ctx)?;
                // Python iterates a `str` by character and a `dict` by key, which
                // is not what Rust's `into_iter` does for those types.
                let sequence = match iter.as_ref() {
                    Value::String(_) | Value::FormatString { .. } => {
                        format!("{iter_str}.chars().map(|__tarvos_ch| __tarvos_ch.to_string())")
                    }
                    Value::Call {
                        return_type: Type::String,
                        ..
                    } => {
                        format!("{iter_str}.chars().map(|__tarvos_ch| __tarvos_ch.to_string())")
                    }
                    Value::Dict { .. } => format!("{iter_str}.keys().cloned()"),
                    _ => iter_str,
                };
                let mapped = if let Some(condition) = condition {
                    let condition_str = Self::emit_value(condition, ctx)?;
                    format!(
                        "{sequence}.into_iter().filter_map(|{target}| if {condition_str} {{ Some({element_str}) }} else {{ None }})"
                    )
                } else {
                    format!("{sequence}.into_iter().map(|{target}| {element_str})")
                };
                format!("{mapped}.collect::<Vec<_>>()")
            }
            Value::Tuple { elements, .. } => {
                let elements_str = elements
                    .iter()
                    .map(|v| Self::emit_value(v, ctx))
                    .collect::<Result<Vec<_>>>()?
                    .join(", ");
                if elements.len() == 1 {
                    format!("({},)", elements_str)
                } else {
                    format!("({})", elements_str)
                }
            }
            Value::Dict { keys, values, .. } => {
                let pairs = keys
                    .iter()
                    .zip(values.iter())
                    .map(|(key, value)| {
                        Ok(format!(
                            "({}, {})",
                            Self::emit_value(key, ctx)?,
                            Self::emit_value(value, ctx)?
                        ))
                    })
                    .collect::<Result<Vec<_>>>()?;
                format!("HashMap::from([{}])", pairs.join(", "))
            }
            Value::Index {
                container,
                index,
                container_type,
                element_type,
            } => {
                let container_str = Self::emit_value(container, ctx)?;
                let index_str = Self::emit_value(index, ctx)?;
                if matches!(container_type, Type::Dict { .. }) {
                    // A `HashMap` lookup already yields a reference, so reading a
                    // non-`Copy` value out of it still needs an owned copy.
                    return Ok(Self::clone_if_owned(
                        format!("{}[&{index_str}]", container_str),
                        element_type,
                    ));
                }
                if let (Type::Tuple(_), Value::Int(index)) = (container_type, index.as_ref()) {
                    return Ok(Self::clone_if_owned(
                        format!("{container_str}.{index}"),
                        element_type,
                    ));
                }
                // A sequence read resolves the index through the runtime so a
                // negative index counts from the end and an out-of-range index
                // raises IndexError, as CPython does.
                if matches!(container_type, Type::String) {
                    return Ok(format!(
                        "__tarvos_str_index(&{container_str}, ({index_str}) as i64)"
                    ));
                }
                if matches!(container_type, Type::Array(_)) {
                    return Ok(Self::clone_if_owned(
                        format!(
                            "{container_str}[__tarvos_index({container_str}.len() as i64, ({index_str}) as i64)]"
                        ),
                        element_type,
                    ));
                }
                Self::clone_if_owned(
                    format!("{container_str}[({index_str} as usize)]"),
                    element_type,
                )
            }
            Value::Slice {
                container,
                lower,
                upper,
                step,
                ..
            } => {
                if step.is_some() {
                    return Err(anyhow::anyhow!(
                        "slice steps are not supported in native Rust codegen"
                    ));
                }
                let container = Self::emit_value(container, ctx)?;
                let lower = lower
                    .as_ref()
                    .map(|v| Self::emit_value(v, ctx))
                    .transpose()?
                    .unwrap_or_else(|| "0_i64".to_string());
                let upper = upper
                    .as_ref()
                    .map(|v| Self::emit_value(v, ctx))
                    .transpose()?
                    .unwrap_or_else(|| format!("{}.len() as i64", container));
                format!(
                    "{}[({} as usize)..({} as usize)].to_vec()",
                    container, lower, upper
                )
            }
            Value::FormatString { parts } => {
                let mut format_string = String::new();
                let mut args = Vec::new();
                for part in parts {
                    match part {
                        tarvos_ir::FormatPart::Literal(value) => {
                            format_string.push_str(&value.replace('{', "{{").replace('}', "}}"));
                        }
                        tarvos_ir::FormatPart::Value {
                            value,
                            format_spec,
                            conversion,
                        } => {
                            let grouped = format_spec
                                .as_deref()
                                .map(Self::python_grouping_separator)
                                .transpose()?
                                .flatten();
                            let rendered_spec = match (grouped, format_spec.as_deref()) {
                                (Some(_), _) | (None, None) => String::new(),
                                (None, Some(spec)) => Self::rust_format_spec(spec),
                            };
                            format_string.push('{');
                            format_string.push_str(&rendered_spec);
                            format_string.push('}');
                            let mut rendered = Self::emit_value(value, ctx)?;
                            if let Some(separator) = grouped {
                                rendered = format!(
                                    "__tarvos_group_numeric({}, '{}')",
                                    rendered, separator
                                );
                            }
                            args.push(match conversion.as_deref() {
                                Some("r") | Some("a") => format!("{:?}", rendered),
                                _ => rendered,
                            });
                        }
                    }
                }
                if args.is_empty() {
                    format!("{:?}.to_string()", format_string)
                } else {
                    format!("format!({:?}, {})", format_string, args.join(", "))
                }
            }
        })
    }

    /// Clone an indexed read when its element type is not `Copy`.
    ///
    /// Rust cannot move a `String` out of a `Vec` or a `HashMap` by index, so
    /// the read has to produce an owned value. Copy-like element types are left
    /// alone so numeric loops keep their zero-copy access.
    /// Emit Python's `str(x)`.
    ///
    /// The rendering is type-directed because Rust's `Display` disagrees with
    /// Python's `str` in two places: a bool prints as `true` rather than `True`,
    /// and an integral float prints as `4` rather than `4.0`.
    fn emit_str_conversion(argument: &Value, rendered: &str) -> String {
        match argument {
            Value::Bool(flag) => {
                let literal = if *flag { "True" } else { "False" };
                format!("\"{literal}\"")
            }
            // `{:?}` keeps the fractional part for a whole-number float.
            Value::Float(_) => format!("format!(\"{{:?}}\", {rendered})"),
            _ => format!("format!(\"{{}}\", {rendered})"),
        }
    }

    /// Emit Python's truthiness test for a value.
    ///
    /// `x != 0` is only meaningful for integers. For a string or a collection
    /// the correct test is emptiness, and comparing those to `0` does not
    /// compile. Each shape gets the helper that matches it.
    fn emit_truthiness(argument: &Value, rendered: &str) -> String {
        match argument {
            Value::String(_) | Value::FormatString { .. } => {
                format!("__tarvos_truthy_string(&{rendered})")
            }
            Value::List { .. } | Value::ListComp { .. } => {
                format!("__tarvos_truthy_vec(&{rendered})")
            }
            Value::Dict { .. } => format!("__tarvos_truthy_map(&{rendered})"),
            // A bool is already a bool. An int is not: `if 0_i64` does not
            // compile, so an integer has to be compared against zero.
            Value::Bool(_) => rendered.to_string(),
            Value::Int(_) | Value::Int128(_) => format!("(({rendered}) != 0)"),
            // A float compares against 0.0, not 0: Rust will not promote an
            // integer literal to f64, so `x != 0_i64` does not compile here.
            Value::Float(_) => format!("(({rendered}) != 0.0_f64)"),
            // An unknown value: fall back to the numeric comparison, which is
            // the only one Rust can express without knowing the type.
            _ => format!("(({rendered}) != 0_i64)"),
        }
    }

    /// Emit Python's `int(x)`.
    ///
    /// The conversion is chosen from the argument's static type. A blind `as`
    /// is wrong in both directions: `String as i64` does not compile, and
    /// `f64 as i64` silently truncates where Python raises for a non-integral
    /// value. A string needs real parsing, which is what the runtime helper is
    /// for.
    fn emit_int_conversion(argument: &Value, rendered: &str) -> String {
        match argument {
            Value::String(_) | Value::FormatString { .. } => {
                format!("__tarvos_parse_int(&{rendered})")
            }
            Value::Float(_) => format!("({rendered} as i64)"),
            // A bool is an int subclass in Python: int(True) is 1.
            Value::Bool(_) => format!("(if {rendered} {{ 1_i64 }} else {{ 0_i64 }})"),
            Value::Int(_) | Value::Int128(_) => rendered.to_string(),
            _ => format!("({rendered} as i64)"),
        }
    }

    /// Emit Python's `float(x)`.
    ///
    /// `float("3.2")` parses; `float(3)` widens. A blind `as` cannot do the
    /// first and is not a general conversion in either direction.
    fn emit_float_conversion(argument: &Value, rendered: &str) -> String {
        match argument {
            Value::String(_) | Value::FormatString { .. } => {
                format!("__tarvos_parse_float(&{rendered})")
            }
            Value::Int(_) | Value::Int128(_) | Value::Float(_) => {
                format!("({rendered} as f64)")
            }
            _ => format!("({rendered} as f64)"),
        }
    }

    /// Whether a call targets a user-defined function rather than a runtime
    /// helper or a builtin.
    ///
    /// Only user functions take their parameters by value, so only they can
    /// move a caller's binding.
    fn is_user_function(function: &str) -> bool {
        // Both the `__tarvos_*` lowering helpers and the `tarvos_*` runtime
        // helpers take references or mutate in place; only a user function takes
        // its parameters by value.
        if function.starts_with("tarvos_") || function.starts_with("__tarvos_") {
            return false;
        }
        !matches!(
            function,
            "print" | "len" | "str" | "int" | "float" | "bool" | "range" | "sorted"
        )
    }

    /// Which call arguments are owned values that a by-value parameter would
    /// move out of the caller's binding.
    ///
    /// A bare name is the only risky shape: an owned *literal* is a temporary, so
    /// moving it is harmless, and scalars are `Copy`. The IR does not carry a
    /// type for a bare `Name`, so this errs toward cloning. An unnecessary
    /// `.clone()` on a `Copy` type is still valid Rust, whereas omitting one on an
    /// owned type is a hard compile error.
    fn owned_bindings(args: &[Value]) -> Vec<bool> {
        args.iter()
            .map(|arg| matches!(arg, Value::Name(_)))
            .collect()
    }

    fn clone_if_owned(expression: String, element_type: &Type) -> String {
        match element_type {
            Type::Int | Type::Float | Type::Bool | Type::None | Type::Unknown => expression,
            Type::String
            | Type::Array(_)
            | Type::Dict { .. }
            | Type::Tuple(_)
            // A tagged value owns whatever it holds, so it is never `Copy` even
            // when it currently happens to carry an `i64`.
            | Type::Dynamic
            | Type::Object(_) => {
                format!("{expression}.clone()")
            }
        }
    }

